--
-- Estrutura para tabela `eventos`
--

CREATE TABLE `eventos` (
  `id` int NOT NULL,
  `txtid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID amigável ou slug',
  `nome` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descricao` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `imagem` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL da imagem do evento',
  `data_evento` datetime NOT NULL,
  `created_by` int NOT NULL COMMENT 'ID do usuário criador',
  `created_on` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `last_edit_by` int DEFAULT NULL COMMENT 'ID do último editor',
  `last_edit_on` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `link` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `faixa_etaria` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `local` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `estabelecimento` int DEFAULT NULL COMMENT 'FK estabelecimentos.id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

