(41, 'musty-boys-dan-castells-202607082000-ec256288', 'Musty Boys • Dan Castells', 'Noite de Musty Boys • Dan Castells no Vila Dionísio. Gêneros musicais da noite: Folk Rock | Pop Rock. Abertura da casa a partir das 20:00. Programação detalhada: - 21:30 - Palco de Abertura: Musty Boys (Folk Rock) - 00:10 - Palco Principal: Dan Castells (Pop Rock). O Vila Dionísio, fundado em 2004 e com filial em Ribeirão Preto desde 2008, é famoso por seu cardápio extenso de cervejas artesanais premiadas e sua deliciosa coxinha de frango com Catupiry. É o local ideal para desfrutar de boa música e cervejas especiais. Localizado em Rua Eliseu Guilherme, 567 - Jardim Sumaré, Ribeirão Preto. Horário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h. Entrada proibida para menores de 18 anos. Para mais informações ou reservas, entre em contato via WhatsApp (16) 98111-4455 ou e-mail ribeirao@viladionisio.com.br.', 'https://www.viladionisio.com.br/images/events/1782904483.webp', '2026-07-08 20:00:00', 1, '2026-07-08 20:07:49', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-08', '', '18 anos', NULL, 1),
(42, 'dj-rodrigo-mod-monalisa-202607092000-61ea46f3', 'DJ Rodrigo MOD • Monalisa', 'Noite de DJ Rodrigo MOD • Monalisa no Vila Dionísio. Gêneros musicais da noite: Discotecagem | Pop Rock. Abertura da casa a partir das 20:00. Programação detalhada: - 21:30 - Palco Principal: DJ Rodrigo MOD (Discotecagem) - 22:30 - Palco Principal: Monalisa (Pop Rock). O Vila Dionísio, fundado em 2004 e com filial em Ribeirão Preto desde 2008, é famoso por seu cardápio extenso de cervejas artesanais premiadas e sua deliciosa coxinha de frango com Catupiry. É o local ideal para desfrutar de boa música e cervejas especiais. Localizado em Rua Eliseu Guilherme, 567 - Jardim Sumaré, Ribeirão Preto. Horário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h. Entrada proibida para menores de 18 anos. Para mais informações ou reservas, entre em contato via WhatsApp (16) 98111-4455 ou e-mail ribeirao@viladionisio.com.br.', 'https://www.viladionisio.com.br/images/events/1783278469.webp', '2026-07-09 20:00:00', 1, '2026-07-08 20:07:50', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-09', '', '18 anos', NULL, 1),
(43, 'danilo-teoro-versão-dois-202607102000-5c2b8280', 'Danilo Teoro • Versão Dois', 'Noite de Danilo Teoro • Versão Dois no Vila Dionísio. Gêneros musicais da noite: Pop Rock | Pop Rock Moderno. Abertura da casa a partir das 20:00. Programação detalhada: - 21:30 - Palco de Abertura: Danilo Teoro (Pop Rock) - 00:10 - Palco Principal: Versão Dois (Pop Rock Moderno). O Vila Dionísio, fundado em 2004 e com filial em Ribeirão Preto desde 2008, é famoso por seu cardápio extenso de cervejas artesanais premiadas e sua deliciosa coxinha de frango com Catupiry. É o local ideal para desfrutar de boa música e cervejas especiais. Localizado em Rua Eliseu Guilherme, 567 - Jardim Sumaré, Ribeirão Preto. Horário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h. Entrada proibida para menores de 18 anos. Para mais informações ou reservas, entre em contato via WhatsApp (16) 98111-4455 ou e-mail ribeirao@viladionisio.com.br.', 'https://www.viladionisio.com.br/images/events/1783278571.webp', '2026-07-10 20:00:00', 1, '2026-07-08 20:07:50', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-10', '', '18 anos', NULL, 1),
(44, 'whiskey-river-especial-coldplay-imagine-dragons-c-paradise-202607112000-353bca82', 'Whiskey River • Especial Coldplay & Imagine Dragons c/ Paradise', 'Noite de Whiskey River • Especial Coldplay & Imagine Dragons c/ Paradise no Vila Dionísio. Gêneros musicais da noite: Blues | Especial Coldplay & Imagine Dragons. Abertura da casa a partir das 20:00. Programação detalhada: - 21:30 - Palco de Abertura: Whiskey River (Blues) - 00:10 - Palco Principal: Especial Coldplay & Imagine Dragons c/ Paradise (Especial Coldplay & Imagine Dragons). O Vila Dionísio, fundado em 2004 e com filial em Ribeirão Preto desde 2008, é famoso por seu cardápio extenso de cervejas artesanais premiadas e sua deliciosa coxinha de frango com Catupiry. É o local ideal para desfrutar de boa música e cervejas especiais. Localizado em Rua Eliseu Guilherme, 567 - Jardim Sumaré, Ribeirão Preto. Horário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h. Entrada proibida para menores de 18 anos. Para mais informações ou reservas, entre em contato via WhatsApp (16) 98111-4455 ou e-mail ribeirao@viladionisio.com.br.', 'https://www.viladionisio.com.br/images/events/1783278809.webp', '2026-07-11 20:00:00', 1, '2026-07-08 20:07:50', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-11', '', '18 anos', NULL, 1),
(45, 'musty-boys-dan-castells-202607082000-5804e366', 'Musty Boys & Dan Castells', 'Prepare-se para uma noite de música ao vivo no Vila Dionísio Ribeirão Preto nesta quarta-feira, 8 de julho de 2026. A partir das 20:00, o bar abre suas portas para receber os amantes do rock. No Palco de Abertura, às 21:30, Musty Boys traz seu Folk Rock envolvente. Em seguida, no Palco Principal, à 00:10, Dan Castells assume o palco com o melhor do Pop Rock. O Vila Dionísio é um bar renomado, famoso por sua extensa carta de cervejas artesanais e importadas, além da clássica coxinha de frango com Catupiry. A entrada é permitida apenas para maiores de 18 anos, e a casa funciona de quinta a sábado e vésperas de feriado, das 20h às 3h.', 'https://www.viladionisio.com.br/images/events/1782904483.webp', '2026-07-08 20:00:00', 1, '2026-07-08 22:23:49', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-08', '', '18 anos', NULL, 1),
(46, 'dj-rodrigo-mod-monalisa-202607092000-679d92ab', 'DJ Rodrigo MOD & Monalisa', 'A quinta-feira, 9 de julho de 2026, no Vila Dionísio Ribeirão Preto promete ser animada, com abertura às 20:00. O Palco Principal será o centro das atenções: às 21:30, o DJ Rodrigo MOD comanda a Discotecagem, seguido pela banda Monalisa às 22:30, que apresentará seu Pop Rock vibrante. O Vila Dionísio é conhecido pela sua seleção de cervejas nacionais e importadas, bem como sua famosa coxinha de frango com Catupiry. A casa funciona de quinta a sábado e vésperas de feriado, das 20h às 3h, e a entrada é proibida para menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783278469.webp', '2026-07-09 20:00:00', 1, '2026-07-08 22:23:55', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-09', '', '18 anos', NULL, 1),
(47, 'danilo-teoro-versão-dois-202607102000-a72f0ab7', 'Danilo Teoro & Versão Dois', 'Sua sexta-feira, 10 de julho de 2026, no Vila Dionísio Ribeirão Preto começa às 20:00 com muita música. A noite contará com a presença de Danilo Teoro, que subirá ao Palco de Abertura às 21:30 com seu repertório de Pop Rock. Mais tarde, à 00:10, a banda Versão Dois assume o Palco Principal com um show de Pop Rock Moderno. Desfrute da vasta seleção de cervejas e da icônica coxinha de frango com Catupiry. O estabelecimento opera de quinta a sábado e vésperas de feriado, das 20h às 3h, e a entrada é exclusiva para maiores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783278571.webp', '2026-07-10 20:00:00', 1, '2026-07-08 22:23:58', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-10', '', '18 anos', NULL, 1),
(48, 'whiskey-river-especial-coldplay-imagine-dragons-c-paradise-202607112000-76a2d449', 'Whiskey River & Especial Coldplay & Imagine Dragons c/ Paradise', 'Prepare-se para uma super noite de sábado, 11 de julho de 2026, no Vila Dionísio Ribeirão Preto, com abertura às 20:00. O Palco de Abertura receberá a banda Whiskey River às 21:30, trazendo o melhor do Blues. O ponto alto da noite será o Palco Principal, que à 00:10 terá um Especial Coldplay & Imagine Dragons com a banda Paradise, prometendo um show imperdível. No Vila Dionísio, você encontra uma excelente variedade de cervejas e a famosa coxinha de frango com Catupiry. Lembre-se que a casa funciona de quinta a sábado e vésperas de feriado, das 20h às 3h, e a entrada é proibida para menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783278809.webp', '2026-07-11 20:00:00', 1, '2026-07-08 22:24:01', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-11', '', '18 anos', NULL, 1),
