(98, 'vila-dionísio-apresenta-dj-rodrigo-mod-doma-202607162130-65a7cbf2', 'Vila Dionísio apresenta: DJ Rodrigo MOD & Doma', 'Programação completa para 16/07/2026:\n- DJ Rodrigo MOD (Discotecagem) se apresenta às 21:30 no Palco Principal.\n- Doma (Tributo a Charlie Brown Jr., O Rappa & Rock BR 90) se apresenta às 22:30 no Palco Principal.\n\nO Vila Dionísio em Ribeirão Preto, fundado em 2008 como filial do bar de São José do Rio Preto (2004), é conhecido por seu extenso cardápio de cervejas nacionais e importadas e por elevar o padrão das casas de rock. Desde 2014, produz sua própria cerveja artesanal, com vários prêmios. O local é famoso pela coxinha de frango com Catupiry.\nHorário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h.\nProibida a entrada de menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783859576.webp', '2026-07-16 21:30:00', 1, '2026-07-17 02:51:44', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-16', '', '18 anos', NULL, 1),
