(101, 'vila-dionísio-apresenta-dj-rodrigo-mod-danilo-teoro-202607232130-346fe357', 'Vila Dionísio apresenta: DJ Rodrigo MOD & Danilo Teoro', 'Programação completa para 23/07/2026:\n- DJ Rodrigo MOD (Discotecagem) se apresenta às 21:30 no Palco Principal.\n- Danilo Teoro (Pop Rock) se apresenta às 22:30 no Palco Principal.\n\nO Vila Dionísio em Ribeirão Preto, fundado em 2008 como filial do bar de São José do Rio Preto (2004), é conhecido por seu extenso cardápio de cervejas nacionais e importadas e por elevar o padrão das casas de rock. Desde 2014, produz sua própria cerveja artesanal, com vários prêmios. O local é famoso pela coxinha de frango com Catupiry.\nHorário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h.\nProibida a entrada de menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783860531.webp', '2026-07-23 21:30:00', 1, '2026-07-17 02:51:48', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-23', '', '18 anos', NULL, 1),
(102, 'vila-dionísio-apresenta-ratlook-everlong-202607242130-b2fbfc9f', 'Vila Dionísio apresenta: Ratlook & Everlong', 'Programação completa para 24/07/2026:\n- Ratlook (Folk Rock) se apresenta às 21:30 no Palco de Abertura.\n- Everlong (Foo Fighters & Variados) se apresenta às 00:10 no Palco Principal.\n\nO Vila Dionísio em Ribeirão Preto, fundado em 2008 como filial do bar de São José do Rio Preto (2004), é conhecido por seu extenso cardápio de cervejas nacionais e importadas e por elevar o padrão das casas de rock. Desde 2014, produz sua própria cerveja artesanal, com vários prêmios. O local é famoso pela coxinha de frango com Catupiry.\nHorário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h.\nProibida a entrada de menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783859958.webp', '2026-07-24 21:30:00', 1, '2026-07-17 02:51:48', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-24', '', '18 anos', NULL, 1),
(103, 'vila-dionísio-apresenta-zé-chavala-ch4nges-202607252130-cc9feaf8', 'Vila Dionísio apresenta: Zé Chavala & Ch4nges', 'Programação completa para 25/07/2026:\n- Zé Chavala (Pop Rock) se apresenta às 21:30 no Palco de Abertura.\n- Ch4nges (Especial Linkin Park, System of a Down & Slipknot) se apresenta às 00:10 no Palco Principal.\n\nO Vila Dionísio em Ribeirão Preto, fundado em 2008 como filial do bar de São José do Rio Preto (2004), é conhecido por seu extenso cardápio de cervejas nacionais e importadas e por elevar o padrão das casas de rock. Desde 2014, produz sua própria cerveja artesanal, com vários prêmios. O local é famoso pela coxinha de frango com Catupiry.\nHorário de funcionamento: De quinta a sábado e vésperas de feriado, das 20h às 3h.\nProibida a entrada de menores de 18 anos.', 'https://www.viladionisio.com.br/images/events/1783860059.webp', '2026-07-25 21:30:00', 1, '2026-07-17 02:51:49', NULL, '2026-07-23 03:12:25', 'https://www.viladionisio.com.br/ribeirao/eventos/2026-07-25', '', '18 anos', NULL, 1),
(104, 'west-side-story-cia-minaz-202607042000-19cebd35', 'West Side Story – Cia Minaz', 'West Side Story – Cia Minaz\n\nRegras e informações gerais do Theatro Pedro II:\nInformamos que não é permitido o acesso de crianças menores de 12 anos na Fila \"A\" dos setores Balcão Nobre e Balcão Simples, conforme determinação do Ministério Público, por questões de segurança, devido à altura do guarda corpo.\n- Não será permitida a entrada após o início do espetáculo, não havendo troca de ingresso e nem devolução do dinheiro.\n- Para melhor conservação do Theatro Pedro II é proibido o consumo de bebidas e alimentos dentro das salas de espetáculos.', 'https://www.theatropedro2.com.br/imagem_texto/20260612_163019_capa-site-40-png', '2026-07-04 20:00:00', 1, '2026-07-17 02:55:27', NULL, '2026-07-23 03:12:25', 'https://www.theatropedro2.com.br/espetaculo.php?id=1785&west-side-story-cia-minaz', 'Verificar no link de compra', '', NULL, 3),
