--
-- Estrutura para tabela `expositores`
--

CREATE TABLE `expositores` (
  `id` int UNSIGNED NOT NULL,
  `txtid` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nome` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resumo` varchar(400) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descricao` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `categoria` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grupo` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'artesao',
  `logo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_destaque` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `whatsapp` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ordem` int NOT NULL DEFAULT '0',
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `created_on` datetime DEFAULT CURRENT_TIMESTAMP,
  `edited_on` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Despejando dados para a tabela `expositores`
--

INSERT INTO `expositores` (`id`, `txtid`, `nome`, `slug`, `resumo`, `descricao`, `categoria`, `grupo`, `logo`, `foto_destaque`, `instagram`, `whatsapp`, `ordem`, `ativo`, `created_on`, `edited_on`) VALUES
(1, '60fedafbffdc', 'Ateliê Beleza Bruta', 'beleza_bruta', 'Peças únicas em concreto, feitas à mão, que revelam a beleza dos materiais rústicos.', 'O Ateliê Beleza Bruta nasceu em 2025, criado pela artista e professora Ju Pedreira, com o propósito de revelar a beleza que existe nos materiais rústicos e robustos. Cada peça é única e inteiramente feita à mão, utilizando moldes obtidos de materiais recicláveis que ganham nova vida no processo criativo.\r\n\r\nA base do trabalho é o concreto, enriquecido com elementos naturais, criando uma variedade de objetos de decoração e artísticos que despertam sentidos e memórias.\r\n\r\nVelas\r\nAs velas são aromáticas com base em concreto, explorando diferentes tamanhos, essências e cores. Cada uma é pensada para dialogar com elementos naturais, criando composições que despertam os sentidos e contam histórias.\r\n\r\nMandalas e incensários\r\nAs mandalas e os incensários nascem do encontro entre a força do concreto e a delicadeza do gesto manual. Cada peça é pintada à mão, uma a uma, em um processo lento e intuitivo, onde cores, formas e símbolos se organizam. Não existem peças iguais — cada mandala é um exercício de presença, intenção e equilíbrio.\r\n\r\nVasos\r\nOs vasos revelam a beleza do concreto em formas orgânicas e atemporais. Criados para acolher plantas, flores ou simplesmente ocupar o espaço como objetos de contemplação, cada peça é moldada e finalizada manualmente, valorizando texturas, imperfeições e a singularidade de cada criação.\r\n\r\nBowls\r\nOs bowls unem funcionalidade e expressão artística. Feitos em concreto e finalizados à mão, transitam entre o uso cotidiano e a decoração, recebendo velas, joias, pequenos objetos ou simplesmente compondo ambientes com sua presença marcante.\r\n\r\nBijuterias\r\nAs bijuterias transformam o concreto em leveza. Desenvolvidas com uma técnica especial que reduz o peso sem perder a resistência do material, são pintadas e finalizadas à mão, tornando cada peça exclusiva.', 'Concreto e decoração', 'artesao', '60a40e1ee4bb7ab80670e0b6f566e4cf.jpeg', 'e3d2c9d3f33fa3f0d5ffb4f22c0a1f8a.jpeg', 'jupedreira.atelie', '16991480570', 1, 1, '2026-07-24 00:50:53', '2026-08-17 20:55:56'),
(2, '2b1a2b34bf65', 'Atelier Iara Nicola', 'iara', 'Argila, madeira, aquarela e ilustração — arte em cada detalhe, com aulas e oficinas.', 'No Atelier Iara Nicola, a arte está presente em cada detalhe. Aqui, a argila ganha forma, a madeira recebe novas cores, a delicadeza da aquarela conta histórias e as ilustrações nascem da imaginação. Além de criar peças autorais, compartilho esse conhecimento por meio de aulas e oficinas, acreditando que a arte transforma, aproxima pessoas e desperta talentos. Tudo o que faço carrega dedicação, sensibilidade e, acima de tudo, muito amor pela arte.', 'Cerâmica e artes', 'artesao', 'a05231da31febb40f74ae2074df30681.jpeg', 'eff4b0bcc1651dbc29a201c999ad6265.jpeg', 'atelier_iara_nicola', '35997010196', 2, 1, '2026-07-24 00:50:53', '2026-08-17 20:54:12'),
(3, '05f342d531ea', 'Bolachinhas Caseiras Isa & Gui', 'isa_gui', 'Bolachinhas caseiras feitas com dedicação, carinho e o desejo de levar sabor especial à mesa.', 'Olá! Meu nome é Isabel e sou a pessoa por trás das Bolachinhas Caseiras Isa & Gui.\r\n\r\nHá seis anos transformei uma paixão em profissão. Cada bolachinha que produzo é feita com dedicação, carinho e o desejo de levar um sabor especial para a mesa de cada cliente. Sou responsável por toda a produção, pelo atendimento e pelos pedidos, enquanto meu esposo, que trabalha em outra profissão, é meu grande parceiro nas entregas e me incentiva diariamente nessa caminhada.\r\n\r\nHoje tenho a alegria de dizer que vivo da renda das bolachinhas caseiras. Essa conquista é resultado de muito trabalho, persistência e amor pelo que faço. Acredito que o verdadeiro ingrediente de um produto artesanal é o cuidado colocado em cada detalhe.\r\n\r\nSou formada em Técnico de Enfermagem, mas não atuo na área. A vida me conduziu ao empreendedorismo, e encontrei na produção artesanal uma forma de realizar meus sonhos, servir às pessoas e construir uma história da qual me orgulho muito.\r\n\r\nParticipar deste encontro é uma oportunidade de compartilhar minha trajetória, aprender com outros empreendedores e mostrar que, com dedicação e paixão, um sonho pode se transformar em um negócio que alimenta não apenas famílias, mas também esperança e realização.\r\n\r\nÉ um prazer estar aqui. Obrigada por fazer parte dessa história.', 'Doces artesanais', 'alimentacao', '73ab10cb80b9b421d380c1715c7c851a.jpeg', 'ce895c4f717da8f01d462c300f6e460e.jpeg', 'bolachinhas_caseira_', '', 10, 1, '2026-07-24 00:50:53', '2026-08-17 20:56:57'),
(4, '4cc58de77b7d', 'Tomate Pelado Pizzas', 'tomate_pelado', 'Massas fermentadas com tempo e carinho — pizza artesanal que transforma ingredientes simples em encontro.', 'A Tomate Pelado Pizzas nasceu da certeza de que cozinhar é uma forma de amar.\r\n\r\nEm um determinado momento da minha vida, percebi que algo tão simples quanto farinha, água, fermento e tomate podia se transformar em uma verdadeira obra de arte. Mais do que misturar ingredientes, fazer pizza passou a ser uma maneira de criar momentos, despertar memórias e aproximar pessoas ao redor da mesa.\r\n\r\nFoi então que decidi viver daquilo que fazia meu coração vibrar.\r\n\r\nAcredito que Deus nos concede dons para servir ao próximo, e encontrei na gastronomia uma forma de exercer esse propósito. Cada massa fermentada lentamente, cada ingrediente escolhido com carinho e cada pizza que sai do forno carregam gratidão, dedicação e o desejo de proporcionar uma experiência especial.\r\n\r\nParticipar do 2º Encontro de Ceramistas é uma grande alegria, pois enxergamos muitas semelhanças entre a cerâmica e a pizza artesanal. Ambas exigem tempo, paciência, técnica e sensibilidade. Ambas transformam elementos simples em algo único, feito pelas mãos e pelo coração.\r\n\r\nSe hoje a Tomate Pelado Pizzas existe, é porque acreditamos que a boa comida tem o poder de conectar pessoas, criar lembranças e celebrar a vida.\r\n\r\nSeja muito bem-vindo à nossa mesa.\r\n\r\n\"Tudo quanto fizerem, façam de todo o coração, como para o Senhor.\"\r\nColossenses 3:23', 'Pizza artesanal', 'alimentacao', 'c64aeb4c50c718c30f9a7cee2b9b3999.jpeg', 'c523fb78afb26a7f85e08fe7080bfa14.jpeg', 'tomatepeladopizzas', '15998035629', 20, 1, '2026-07-24 01:13:08', '2026-08-17 20:57:57'),
(5, 'b5e75204ed47', 'Cevada Pura', 'cevada_pura', 'Chopp artesanal para brindar encontros — sabor, dedicação e confraternização.', 'CEVADA PURA – UMA HISTÓRIA DE SABOR E DEDICAÇÃO\r\n\r\nÉ com muita alegria que participo do Encontro de Ceramistas levando a Cevada Pura, uma marca que faz parte da minha trajetória há anos.\r\n\r\nA Cevada Pura nasceu do sonho e da dedicação do meu irmão, que transformou seu conhecimento e sua paixão pelo universo cervejeiro em um produto de qualidade. Ao longo dos anos, tive a oportunidade de fazer parte dessa história, trabalhando com a venda do chopp artesanal e levando essa experiência para diferentes momentos e encontros.\r\n\r\nMais do que oferecer uma bebida, a Cevada Pura busca proporcionar momentos de confraternização, encontros entre amigos e experiências especiais em torno de um bom chopp.\r\n\r\nAcreditamos que existe uma conexão entre a produção artesanal e a valorização do feito à mão: assim como cada peça de cerâmica carrega a identidade e a criatividade de quem a produz, cada estilo de chopp possui características próprias, resultado de cuidado, dedicação e paixão.\r\n\r\nEstar presente neste evento é celebrar a arte, a criatividade e o encontro de pessoas que valorizam produtos feitos com história e propósito.\r\n\r\nCevada Pura – um chopp artesanal para brindar momentos especiais.', 'Cerveja artesanal', 'alimentacao', '8f9957c7ff4bd3808b1c4e417add6e4e.jpeg', 'd931165b3b037f0fe6b972965bc12912.jpeg', '', '', 30, 1, '2026-07-24 01:13:09', '2026-08-17 20:58:20'),
(6, 'b5701121a2e0', 'Nino Cerâmica', 'nino_ceramica', 'Nino cerâmica nasceu leve, descontraída. Mas não é por isso que não há propósito. A natureza nos proporciona infinitas formas de criar. Com o barro, argila de forma mais técnica, é possível dar vida à ideias que rompem com o padrão. Eu, Nino, crio peças que transmitem sentimen...', 'Nino cerâmica nasceu leve, descontraída. Mas não é por isso que não há propósito. A natureza nos proporciona infinitas formas de criar. Com o barro, argila de forma mais técnica, é possível dar vida à ideias que rompem com o padrão.  Eu, Nino, crio peças que transmitem sentimentos e aquecem o coração de quem as usam. Transformar, criar, cuidar.', 'Cerâmica', 'artesao', 'expositores/nino_ceramica/logo.jpeg', 'expositores/nino_ceramica/foto_01.jpeg', 'nino.ceramica', '', 50, 1, '2026-08-18 00:43:18', '2026-08-18 01:03:07'),
(7, '317f172975e8', 'Telma Lopes', 'telma_lopes', 'Meu nome é Telma e há mais de 17 anos transformo fios, tecidos e muito carinho em peças artesanais feitas à mão.', 'Meu nome é Telma e há mais de 17 anos transformo fios, tecidos e muito carinho em peças artesanais feitas à mão.\n\nMinha trajetória começou como uma forma de complementar a renda da família. Com dedicação, amor pelo artesanato e a confiança dos meus clientes, essa paixão cresceu e, hoje, tenho o privilégio de viver da arte que tanto amo.\n\nTrabalho com costura criativa e diversas técnicas artesanais, mas foi no crochê que encontrei minha verdadeira paixão. Cada peça é produzida com cuidado, acabamento impecável e atenção aos mínimos detalhes, valorizando a qualidade e a beleza do trabalho artesanal.\n\nTe convido para o 2⁰ encontro de cerâmista e venha  conhecer um pouco da minha história através de cada peça que será feita com muito amor e carinho.Espero que você sinta, em cada ponto, o mesmo amor que coloco em tudo o que faço.', 'Crochê', 'artesao', 'expositores/telma_lopes/logo.jpeg', 'expositores/telma_lopes/foto_01.jpeg', 'telmalopes_croche', NULL, 60, 1, '2026-08-18 00:43:18', NULL),
(8, '164e5581f5c0', 'Mãos de Carolina', 'maos_de_carolina', 'Sou Ana Carolina — fisioterapeuta há 15 anos e ceramista há 5! A cerâmica artesanal é, para mim, a poesia feita com as mãos: é transformar a argila, com calma e intenção, em peças únicas que carregam histórias, marcas e alma. Nenhuma peça é igual à outra — e é justamente isso...', 'Sou Ana Carolina — fisioterapeuta há 15 anos e ceramista há 5!\nA cerâmica artesanal é, para mim, a poesia feita com as mãos: é transformar a argila, com calma e intenção, em peças únicas que carregam histórias, marcas e alma.\nNenhuma peça é igual à outra — e é justamente isso que torna cada uma tão especial.', 'Cerâmica', 'artesao', 'expositores/maos_de_carolina/foto_01.jpeg', 'expositores/maos_de_carolina/foto_01.jpeg', 'maosdecarolinaceramica', NULL, 70, 1, '2026-08-18 00:43:18', NULL),
(9, 'ce9817796c27', 'PRYA Cerâmicas', 'prya_ceramicas', 'Sou a Priscilla e iniciei minha jornada com a cerâmica em 2021. Tudo começou com uma vontade simples: criar algo com minhas próprias mãos. Vi um jogo de pratos e, em vez de comprar, senti que queria fazer os meus. Essa curiosidade me levou a pesquisar, buscar cursos e, sem per...', 'Sou a Priscilla e iniciei minha jornada com a cerâmica em 2021. Tudo começou com uma vontade simples: criar algo com minhas próprias mãos. Vi um jogo de pratos e, em vez de comprar, senti que queria fazer os meus. Essa curiosidade me levou a pesquisar, buscar cursos e, sem perceber, a cerâmica passou a fazer parte da minha vida.\nHoje desenvolvo peças utilitárias com estética orgânica e contemporânea, valorizando formas naturais, texturas sutis e a beleza do feito à mão. Meu trabalho busca unir funcionalidade e sensibilidade, criando peças pensadas para fazer parte da rotina das pessoas e acompanhar histórias.', 'Cerâmica', 'artesao', 'expositores/prya_ceramicas/foto_01.jpeg', 'expositores/prya_ceramicas/foto_01.jpeg', 'pryaceramicas', NULL, 80, 1, '2026-08-18 00:43:18', NULL),
(10, '6df96ff8eaa0', 'Lume Saboaria Artesanal', 'lume_saboaria_artesanal', 'Somos a Lume Saboaria Artesanal, criada por Louise Desirièe Arenare, advogada, e Fabíola dos Santos, dentista.', 'Somos a Lume Saboaria Artesanal, criada por Louise Desirièe Arenare, advogada, e Fabíola dos Santos, dentista.\n\nEm meio à rotina das nossas profissões, encontramos na saboaria artesanal um espaço para criar com calma, sensibilidade e propósito. O que começou como um hobby tornou-se uma forma de transformar ingredientes naturais em experiências de cuidado, bem-estar e aconchego.\n\nCada sabonete, vela e produto de perfumaria é feito artesanalmente, respeitando o tempo de cada etapa e valorizando a beleza dos pequenos detalhes.\n\nÉ uma alegria participar da Feira dos Ceramistas e compartilhar um pouco da nossa essência com você. Esperamos que cada aroma e cada criação despertem a mesma sensação de carinho e cuidado que nos inspira todos os dias.\n\nLume Saboaria Artesanal — cuidado que perfuma, acolhe e permanece.', 'Saboaria artesanal', 'artesao', 'expositores/lume_saboaria_artesanal/foto_01.jpeg', 'expositores/lume_saboaria_artesanal/foto_01.jpeg', 'lume.saboaria.artesanal', NULL, 90, 1, '2026-08-18 00:43:18', NULL),
(11, '015165fb1328', 'Artesanal Tropical', 'artesanal_tropical', 'Sou Elis Regina, e desde 2018 transformo fragrâncias em experiências 🫧 Trabalho com a saboaria artesanal, perfumaria, cosméticos e velas. Tudo criado com cuidado, qualidade e um toque sensorial em cada detalhe.', 'Sou Elis Regina, e desde 2018 transformo fragrâncias em experiências 🫧\nTrabalho com a saboaria artesanal, perfumaria, cosméticos e velas. Tudo criado com cuidado, qualidade e um toque sensorial em cada detalhe.\n\nE dessa vez, vou levar tudo isso para um encontro cheio de criatividade💛\nTe espero no 2• encontro de ceramistas, um espaço que reúne talentos incríveis, feito por artesãos que colocam alma no que criam.', 'Saboaria artesanal', 'artesao', 'expositores/artesanal_tropical/foto_01.jpeg', 'expositores/artesanal_tropical/foto_01.jpeg', 'atelieartesanaltropical', NULL, 100, 1, '2026-08-18 00:43:18', NULL),
(12, 'c02e8d8fbd33', 'Msytic Artesanatos', 'msytic_artesanatos', 'Sou Beatriz, dona da Msytic Artesanatos. Comecei a fazer crochê no final de 2023 para passar o tempo e aos poucos fui descobrindo minha paixão pelo crochê. Hoje trabalho com peças de vestuário, acessórios e também itens de decoração, todas essas peças são feitas com muito amor...', 'Sou Beatriz, dona da Msytic Artesanatos.\r\nComecei a fazer crochê no final de 2023 para passar o tempo e aos poucos fui descobrindo minha paixão pelo crochê.\r\nHoje trabalho com peças de vestuário, acessórios e também itens de decoração, todas essas peças são feitas com muito amor e carinho!', 'Crochê', 'artesao', 'expositores/msytic_artesanatos/logo.jpeg', '632d2174c90aedfbf474989be754633b.png', 'mystic.artesanatos', '', 110, 1, '2026-08-18 00:43:19', '2026-08-18 01:04:26'),
(13, '86342deb9194', 'Empório Quem Comeu o Meu Queijo', 'emporio_quem_comeu_o_meu_queijo', 'Empório Quem Comeu o Meu Queijo. Trabalhamos com Queijo Canastra original e premiado. Temos também o melhor de Minas Gerais em doces, cachaças e café.', 'Empório Quem Comeu o Meu Queijo. Trabalhamos com Queijo Canastra original e premiado. Temos também o melhor de Minas Gerais em doces, cachaças e café.', 'Queijos e doces', 'alimentacao', 'expositores/emporio_quem_comeu_o_meu_queijo/foto_01.jpeg', 'expositores/emporio_quem_comeu_o_meu_queijo/foto_01.jpeg', NULL, NULL, 120, 1, '2026-08-18 00:43:19', NULL),
(14, '566cd556814f', 'Flor de Trigo', 'flor_de_trigo', 'Nós somos a Polyana e a Mariana. Irmãs e sócias na Flor de Trigo. A Polyana é formada em gastronomia e panificação, trabalha na área desde 2018, e é apaixonada pelo processo artesanal. A Mariana sempre gostou de tecnologia, organização e comunicação. Juntas unimos essas áreas...', 'Nós somos a Polyana e a Mariana. Irmãs e sócias na Flor de Trigo.  A Polyana é formada em gastronomia e panificação, trabalha na área desde 2018, e é apaixonada pelo processo artesanal. A Mariana sempre gostou de tecnologia, organização e comunicação. Juntas unimos essas áreas ao empreendedorismo e ao trabalho artesanal. Trabalhamos com pães de fermentação natural e tradicional, salgados, bolos caseiros e cookies. Tudo feito à mão e com carinho. Porque acreditamos que o sabor nasce do cuidado.', 'Panificação', 'alimentacao', 'e2aa066f1bb772a369b3625faddb0243.png', '4e3975246779410f79d4c948e351ce60.png', 'florde_trigo', '16991283335', 130, 1, '2026-08-18 00:43:19', '2026-08-18 00:56:31'),
(15, '99e6ecb86004', 'Café JC - Elizabeth Rezende', 'cafe_jc_elizabeth_rezende', 'Eu sempre tive simpatia e interesse pelas coisas do campo. Há quatorze anos, juntamente com meu sobrinho, adquiri um pequeno sítio. Eu não queria apenas contemplar a natureza. Respeito e valorizo o solo que permite a produção de uma enorme diversidade de alimentos. Gosto de mu...', 'Eu sempre tive simpatia e interesse pelas coisas do campo.\nHá quatorze anos, juntamente com meu sobrinho, adquiri um pequeno sítio.\nEu não queria apenas contemplar a natureza.\nRespeito e valorizo o solo que permite a produção de uma enorme diversidade de alimentos.\nGosto de muitas culturas e penso que o café é uma das mais atraentes.\nAssim, quis implantar uma pequena lavoura de café.\nComo resultado estou inserida no maravilhoso mundo do café.', 'Café', 'alimentacao', 'expositores/cafe_jc_elizabeth_rezende/logo.jpeg', 'expositores/cafe_jc_elizabeth_rezende/foto_01.jpeg', NULL, NULL, 140, 1, '2026-08-18 00:43:19', NULL),
(16, '3963c765b100', 'Marici Cerâmica', 'marici_ceramica', 'Tem gente que encontra o barro… e tem gente que parece que o barro estava esperando por ela.', 'Tem gente que encontra o barro… e tem gente que parece que o barro estava esperando por ela.\n\nA história da Marici Cerâmica começou há apenas três anos, mas quem olha para suas peças percebe rapidamente que ali já existe muita dedicação, sensibilidade e amor pelo fazer manual.\n\nEntre um punhado de argila, uma ideia que nasce e mãos dispostas a experimentar, Marici foi descobrindo aos poucos esse universo encantador da cerâmica. E, desde então, não parou mais de aprender, criar e se surpreender com tudo aquilo que pode nascer do barro.\n\nDetalhista e caprichosa, ela gosta de acompanhar cada etapa, respeitando o tempo da argila e buscando sempre aperfeiçoar sua técnica. E é bonito acompanhar essa caminhada: a cada fornada surgem novas formas, novas ideias, novas cores e peças cada vez mais cheias de personalidade.\n\nPorque é assim com a cerâmica… a gente começa querendo aprender a modelar o barro e, quando percebe, é o barro que também vai nos transformando.\n\nE é justamente essa troca, essa paixão pelo feito à mão e essa vontade de criar que queremos reunir no 2º Encontro de Ceramistas, Aprendizes e Artesãos.\n\nSerá uma alegria ter a Marici Cerâmica conosco, trazendo suas peças, sua criatividade e um pedacinho de sua história.\n\nVenha conhecer de perto o trabalho da Marici, conversar com quem faz, descobrir as histórias por trás das peças e celebrar conosco a beleza do artesanal.\n\nPorque quando mãos, barro e criatividade se encontram, sempre nasce alguma coisa especial.', 'Cerâmica', 'artesao', 'expositores/marici_ceramica/foto_01.jpeg', 'expositores/marici_ceramica/foto_01.jpeg', NULL, NULL, 150, 1, '2026-08-18 00:43:19', NULL),
(17, 'db3fbcc72c96', 'Vânia', 'vania', 'Sou a Vânia. Quando me aposentei e voltei para a minha cidade, senti que era hora de começar um novo capítulo. Queria algo que ocupasse minhas mãos, despertasse minha criatividade e, principalmente, aquecesse o coração.', 'Sou a Vânia.\nQuando me aposentei e voltei para a minha cidade, senti que era hora de começar um novo capítulo. Queria algo que ocupasse minhas mãos, despertasse minha criatividade e, principalmente, aquecesse o coração.\n\nFoi então que o barro apareceu no meu caminho.\n\nNo começo, era apenas a vontade de aprender algo novo… mas bastou colocar as mãos na argila para nascer uma paixão. Entre apertar, modelar, esperar, transformar e recomeçar, percebi que não era só o barro que ganhava novas formas — eu também estava me reinventando.\n\nA cerâmica me ensinou que cada coisa tem seu tempo. Que nem sempre precisamos ter pressa. E que, muitas vezes, são justamente as marcas das nossas mãos que tornam uma peça única e cheia de história.\n\nHoje, a cerâmica é muito mais do que um trabalho para mim. É encontro, troca, acolhimento e alegria. É transformar um simples pedaço de terra em algo que carrega sentimento.\n\nE pensar que tudo começou com uma vontade de ocupar o tempo…\nNo fim, foi o barro que acabou preenchendo meus dias — e meu coração.', 'Cerâmica', 'artesao', 'expositores/vania/foto_01.jpeg', 'expositores/vania/foto_01.jpeg', NULL, NULL, 160, 1, '2026-08-18 00:43:19', NULL),
(18, '949c0a06f3b5', 'Atelie Rita Nogueira', 'atelie_rita_nogueira', 'Há dois anos, a costura criativa entrou na vida da Rita e rapidamente se transformou em paixão. Hoje, entre tecidos, linhas, cores e muitas ideias, ela cria peças bonitas, úteis e feitas com todo carinho.', 'Há dois anos, a costura criativa entrou na vida da Rita e rapidamente se transformou em paixão. Hoje, entre tecidos, linhas, cores e muitas ideias, ela cria peças bonitas, úteis e feitas com todo carinho.\n\nEm seu trabalho você encontra bolsas, nécessaires, toalhas de banho, toalhas de mesa, panos de prato e peças em patchwork, sempre unindo beleza, qualidade e funcionalidade.\n\nE tem notícia boa: a Rita estará com a gente no 2º Encontro de Ceramistas, Aprendizes e Artesãos de Arceburgo!', 'Costura criativa', 'artesao', 'expositores/atelie_rita_nogueira/foto_01.jpeg', 'expositores/atelie_rita_nogueira/foto_01.jpeg', 'atelie_ritanogueira2', NULL, 170, 1, '2026-08-18 00:43:19', NULL),
(19, 'd993bae593f5', 'Art Sabor Confeitaria', 'art_sabor_confeitaria', 'Era uma vez uma cocada… e um sonho que foi ficando cada vez mais doce!', 'Era uma vez uma cocada… e um sonho que foi ficando cada vez mais doce!\r\n\r\nEu sou Janaína Ribeiro, confeiteira e apaixonada por transformar açúcar, carinho e criatividade em momentos especiais. Há 10 anos nasceu a Art’Sabor Confeitaria, começando de um jeitinho simples: com a produção de cocadas e muita vontade de fazer dar certo.\r\n\r\nDe cocada em cocada, o sonho cresceu. Vieram novos sabores, novas receitas, bolos, doces e muitas comemorações para adoçar. Hoje, preparo bolos e doces personalizados para aniversários, casamentos e tantos outros momentos que merecem ser celebrados.\r\n\r\nPor aqui, cada encomenda ganha uma pitadinha de criatividade, uma porção generosa de cuidado e aquele ingrediente que não pode faltar: amor pelo que faço!\r\n\r\nPorque um doce nunca é só um doce. Ele pode guardar o sorriso de um aniversário, a emoção de um casamento, um abraço, um encontro e aquelas lembranças gostosas que ficam para sempre.\r\n\r\nJá são 10 anos adoçando histórias, e continuo com a mesma alegria de quando tudo começou — inventando sabores, aprendendo, criando e participando dos momentos especiais de cada cliente.\r\n\r\nAfinal, a vida já é cheia de histórias…\r\ne algumas delas merecem ser contadas com açúcar, afeto e um pedacinho de bolo!', 'Confeitaria', 'alimentacao', '77c8238fecfd1f783ec754cd30e8a11e.png', '53e05310607c591494e20291dcb01dd0.png', 'janaina_artsabor_confeitaria', '', 180, 1, '2026-08-18 00:43:20', '2026-08-18 01:02:17');

